  case "embeddings":
   if seen { return out, fmt.Errorf("duplicate embeddings") }; seen = true
   token, err := d.Token(); if err != nil || token != json.Delim('[') { return out, fmt.Errorf("expected embeddings array") }
   for d.More() {
    if len(out.Embeddings) >= rows { return out, fmt.Errorf("too many embeddings") }
    token, err := d.Token(); if err != nil || token != json.Delim('[') { return out, fmt.Errorf("expected vector") }
