     vector = append(vector, number)
    }
    if _, err := d.Token(); err != nil { return out, err }
    out.Embeddings = append(out.Embeddings, vector)
   }
   if _, err := d.Token(); err != nil { return out, err }
  default:
   var ignored json.RawMessage
   if err := d.Decode(&ignored); err != nil { return out, err }
  }
 }
 if _, err := d.Token(); err != nil { return out, err }
 if _, err := d.Token(); err != io.EOF { return out, fmt.Errorf("trailing response data") }
 return out, nil
}
